import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Reg矢量计算","link":"/api/SIMD-API/c_api/reg_compute/reg_compute"},{"text":"Reg数据搬出","link":"/api/SIMD-API/c_api/reg_compute/store/store"},{"text":"asc_storeunalign_post","link":"/api/SIMD-API/c_api/reg_compute/store/asc_storeunalign_post"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/reg_compute/store/asc_storeunalign_post.md","filePath":"api/SIMD-API/c_api/reg_compute/store/asc_storeunalign_post.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":3,"title":"立即数偏移搬出模式","slug":"立即数偏移搬出模式","link":"#立即数偏移搬出模式"},{"level":4,"title":"dtype支持数据类型","slug":"dtype支持数据类型","link":"#dtype支持数据类型"},{"level":4,"title":"函数原型典型示例","slug":"函数原型典型示例","link":"#函数原型典型示例"},{"level":3,"title":"地址寄存器偏移搬出模式","slug":"地址寄存器偏移搬出模式","link":"#地址寄存器偏移搬出模式"},{"level":4,"title":"dtype支持数据类型","slug":"dtype支持数据类型-1","link":"#dtype支持数据类型-1"},{"level":4,"title":"函数原型典型示例","slug":"函数原型典型示例-1","link":"#函数原型典型示例-1"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"立即数偏移搬出模式","slug":"立即数偏移搬出模式-1","link":"#立即数偏移搬出模式-1"},{"level":3,"title":"地址寄存器偏移搬出模式","slug":"地址寄存器偏移搬出模式-1","link":"#地址寄存器偏移搬出模式-1"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":3,"title":"通用约束","slug":"通用约束","link":"#通用约束"},{"level":3,"title":"立即数偏移搬出模式","slug":"立即数偏移搬出模式-2","link":"#立即数偏移搬出模式-2"},{"level":3,"title":"地址寄存器偏移搬出模式","slug":"地址寄存器偏移搬出模式-2","link":"#地址寄存器偏移搬出模式-2"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788267010000}'),c={name:"api/SIMD-API/c_api/reg_compute/store/asc_storeunalign_post.md"};function t(e,s,o,i,d,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>asc_storeunalign_post</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>将非对齐寄存器中暂存的尾块写入Unified Buffer（UB），用于连续非对齐搬运收尾。本接口提供以下两种模式：</p><ul><li><strong>立即数偏移搬出模式</strong>：通过立即数指定相对目的起始地址的偏移，单位为元素，用户可选择手动更新偏移或更新目的地址，用于配合前序非对齐搬出接口<a href="asc_storeunalign.html">asc_storeunalign</a>或<a href="asc_storeunalign_postupdate.html">asc_storeunalign_postupdate掩码寄存器搬出模式</a>收尾。</li><li><strong>地址寄存器偏移搬出模式</strong>：通过地址寄存器指定相对目的起始地址的偏移，常用于Hardware Loop内偏移随循环计数变化的搬出场景。需要与<a href="../reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>配合使用。用于配合前序非对齐搬出接口<a href="asc_storeunalign_postupdate.html">asc_storeunalign_postupdate地址寄存器偏移搬出模式</a>收尾。</li></ul><p>本接口仅在AIV上生效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><h3 id="立即数偏移搬出模式">立即数偏移搬出模式<a class="header-anchor" href="#立即数偏移搬出模式">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 占位符形式</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span>
</code></pre></div><h4 id="dtype支持数据类型">dtype支持数据类型<a class="header-anchor" href="#dtype支持数据类型">​</a></h4><p><code>dtype</code>支持的数据类型为<code>int4b_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code>。</p><h4 id="函数原型典型示例">函数原型典型示例<a class="header-anchor" href="#函数原型典型示例">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span>
</code></pre></div><h3 id="地址寄存器偏移搬出模式">地址寄存器偏移搬出模式<a class="header-anchor" href="#地址寄存器偏移搬出模式">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 占位符形式</span>
<span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">addr_reg</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span>
</code></pre></div><h4 id="dtype支持数据类型-1">dtype支持数据类型<a class="header-anchor" href="#dtype支持数据类型-1">​</a></h4><p><code>dtype</code>支持的数据类型为<code>int4b_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code>。</p><h4 id="函数原型典型示例-1">函数原型典型示例<a class="header-anchor" href="#函数原型典型示例-1">​</a></h4><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_callee__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">addr_reg</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><h3 id="立即数偏移搬出模式-1">立即数偏移搬出模式<a class="header-anchor" href="#立即数偏移搬出模式-1">​</a></h3><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数在UB中的基地址，类型为<code>__ubuf__ &lt;dtype&gt;*</code>。地址无需32字节对齐，但须按<code>sizeof(dtype)</code>字节对齐。</td></tr><tr><td>unalign_reg</td><td>输入</td><td>非对齐寄存器，类型为<code>vector_store_unalign</code>，长度为32字节。须与前序主搬出接口使用同一个寄存器。</td></tr><tr><td>offset</td><td>输入</td><td>目的操作数结束地址的偏移，类型为<code>int32_t</code>，单位为元素。</td></tr></tbody></table><h3 id="地址寄存器偏移搬出模式-1">地址寄存器偏移搬出模式<a class="header-anchor" href="#地址寄存器偏移搬出模式-1">​</a></h3><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数在UB中的基地址，类型为<code>__ubuf__ &lt;dtype&gt;*</code>。地址无需32字节对齐，但须按<code>sizeof(dtype)</code>字节对齐。</td></tr><tr><td>unalign_reg</td><td>输入</td><td>非对齐寄存器，类型为<code>vector_store_unalign</code>，长度为32字节。须与前序主搬出接口使用同一个寄存器。</td></tr><tr><td>offset</td><td>输入</td><td>目的操作数结束地址的偏移，类型为<code>addr_reg</code>。须与前序主搬出接口使用同一个寄存器。</td></tr></tbody></table><p>非对齐寄存器和地址寄存器的详细说明请参见<a href="../../defs/type/data_type_definition.html">reg数据类型定义</a>。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><h3 id="通用约束">通用约束<a class="header-anchor" href="#通用约束">​</a></h3><ul><li>非AIV调用直接返回。</li><li>本接口在Vector Function（<code>__simd_vf__</code>标记的函数）内调用。</li><li>需要保证目的操作数的地址加上<code>offset</code>对应的偏移地址，访问范围须位于实际可用UB范围内。</li><li>该接口中的目的地址不需要32B对齐，但数据类型为<code>dtype</code>的<code>dst</code>需要<code>sizeof(dtype)</code>字节对齐。</li><li>UB容量上限为256KB，用户可用容量随编译选项与编程场景变化（默认预留6KB SIMD VF栈+2KB Ascend C预留，可用248KB；SIMD+SIMT混编时再划分32KB~128KB作Data Cache，可用容量进一步减少）。目的操作数地址不可超过实际可用容量，否则会报错。</li><li>如果本指令与其他指令存在UB地址重叠，需要插入同步指令<a href="../reg_sync/asc_mem_bar.html">asc_mem_bar</a>，保证多个指令串行化，防止出现异常数据。</li></ul><h3 id="立即数偏移搬出模式-2">立即数偏移搬出模式<a class="header-anchor" href="#立即数偏移搬出模式-2">​</a></h3><ul><li>与<a href="asc_storeunalign.html">asc_storeunalign</a>或<a href="asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>的<strong>掩码寄存器搬出模式</strong>配套使用，需要复用同一个<code>unalign_reg</code>。</li><li>需要保证目的地址加上偏移后的地址，等于<a href="asc_storeunalign.html">asc_storeunalign</a>或<a href="asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>的<strong>掩码寄存器搬出模式</strong>搬运的结束地址，否则无法正确收尾。</li></ul><h3 id="地址寄存器偏移搬出模式-2">地址寄存器偏移搬出模式<a class="header-anchor" href="#地址寄存器偏移搬出模式-2">​</a></h3><ul><li>与<a href="asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>的<strong>地址寄存器偏移搬出模式</strong>配套使用，需要复用同一个非对齐寄存器<code>unalign_reg</code>及地址寄存器。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>将代码保存为<code>example.asc</code>后，可通过<code>bisheng</code>命令编译运行，其中<code>--npu-arch</code>参数需根据实际产品型号指定对应的NPU架构，具体产品与NPU架构的映射关系请参考<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">__NPU_ARCH__</a>。</p><div data-filter="950"><p>以Ascend 950PR/Ascend 950DT产品（对应NPU架构为<code>dav-3510</code>）为例，编译运行命令如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bisheng<span class="w"> </span>example.asc<span class="w"> </span>-o<span class="w"> </span>main<span class="w"> </span>--npu-arch<span class="o">=</span>dav-3510<span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span>./main
</code></pre></div></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;iostream&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;vector&gt;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>
<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;acl/acl.h&quot;</span>

<span class="k">namespace</span><span class="w"> </span><span class="p">{</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">START_OFFSET</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">OUTPUT_BYTES</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">START_OFFSET</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">;</span>

<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">storeunalign_post_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_uint8_t</span><span class="w"> </span><span class="n">src</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_store_unalign</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storeunalign</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">START_OFFSET</span><span class="p">,</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storeunalign_post</span><span class="p">(</span><span class="n">output</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">START_OFFSET</span><span class="p">,</span><span class="w"> </span><span class="n">unalign_reg</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">);</span>
<span class="p">}</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">storeunalign_post_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">output_local</span><span class="p">[</span><span class="mi">288</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">input_local</span><span class="p">[</span><span class="n">ELEMENT_COUNT</span><span class="p">];</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">input_local</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">storeunalign_post_vf</span><span class="p">(</span><span class="n">output_local</span><span class="p">,</span><span class="w"> </span><span class="n">input_local</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">output_local</span><span class="p">,</span><span class="w"> </span><span class="n">OUTPUT_BYTES</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="p">}</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace</span>

<span class="kt">int</span><span class="w"> </span><span class="n">main</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">std</span><span class="o">::</span><span class="n">vector</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">input</span><span class="p">(</span><span class="n">ELEMENT_COUNT</span><span class="p">);</span>
<span class="w">    </span><span class="n">std</span><span class="o">::</span><span class="n">vector</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">output</span><span class="p">(</span><span class="n">OUTPUT_BYTES</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">i</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclInit</span><span class="p">(</span><span class="nb">nullptr</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtSetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">input_device</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">output_device</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">void</span><span class="o">**&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">input_device</span><span class="p">),</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtMalloc</span><span class="p">(</span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="kt">void</span><span class="o">**&gt;</span><span class="p">(</span><span class="o">&amp;</span><span class="n">output_device</span><span class="p">),</span><span class="w"> </span><span class="n">OUTPUT_BYTES</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">,</span><span class="w"> </span><span class="n">input</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_HOST_TO_DEVICE</span><span class="p">);</span>
<span class="w">    </span><span class="n">storeunalign_post_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="n">input_device</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtSynchronizeDevice</span><span class="p">();</span>
<span class="w">    </span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">output</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">OUTPUT_BYTES</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="n">OUTPUT_BYTES</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_DEVICE_TO_HOST</span><span class="p">);</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">passed</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">ELEMENT_COUNT</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="n">passed</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">passed</span><span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="n">output</span><span class="p">[</span><span class="n">START_OFFSET</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">i</span><span class="p">];</span>
<span class="w">    </span><span class="n">std</span><span class="o">::</span><span class="n">cout</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="p">(</span><span class="n">passed</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="s">&quot;[Success] asc_storeunalign_post completed.&quot;</span>
<span class="w">                         </span><span class="o">:</span><span class="w"> </span><span class="s">&quot;[Failed] asc_storeunalign_post output mismatch.&quot;</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="n">std</span><span class="o">::</span><span class="n">endl</span><span class="p">;</span>
<span class="w">    </span><span class="n">aclrtFree</span><span class="p">(</span><span class="n">input_device</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtFree</span><span class="p">(</span><span class="n">output_device</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclrtResetDevice</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">aclFinalize</span><span class="p">();</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">passed</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const u=a(c,[["render",t]]);export{h as __pageData,u as default};
